insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata,pilihan_gambar) values ('宿泊分野','写真の中で「最敬礼」にあたるおじぎはどれですか？','[]'::jsonb,2,'最敬礼は約45度です。お詫びや深い感謝の場面で行います。',610,'04 · おじぎ','Dari gambar, mana yang merupakan 「最敬礼」?','最敬礼 sekitar 45 derajat, dipakai saat meminta maaf atau menyampaikan terima kasih mendalam.','[{"k": "最敬礼", "b": "さいけいれい", "a": "bungkuk 45°"}, {"k": "深い", "b": "ふかい", "a": "mendalam"}, {"k": "感謝", "b": "かんしゃ", "a": "terima kasih"}]'::jsonb,'["aset/img/ojigi/sudut-15.png", "aset/img/ojigi/sudut-30.png", "aset/img/ojigi/sudut-45.png", "aset/img/ojigi/sudut-90.png"]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata,pilihan_gambar) values ('宿泊分野','写真の中で「会釈」にあたるおじぎはどれですか？','[]'::jsonb,0,'会釈は約15度で、軽いあいさつやすれ違いのときに使います。',611,'04 · おじぎ','Dari gambar, mana yang merupakan 「会釈」?','会釈 sekitar 15 derajat, dipakai untuk sapaan ringan atau saat berpapasan.','[{"k": "会釈", "b": "えしゃく", "a": "bungkuk 15°"}, {"k": "すれ違い", "b": "すれちがい", "a": "berpapasan"}, {"k": "軽い", "b": "かるい", "a": "ringan"}]'::jsonb,'["aset/img/ojigi/sudut-15.png", "aset/img/ojigi/sudut-30.png", "aset/img/ojigi/sudut-45.png", "aset/img/ojigi/sudut-90.png"]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata,pilihan_gambar) values ('宿泊分野','写真の中で「敬礼」にあたるおじぎはどれですか？','[]'::jsonb,2,'敬礼は約30度で、一般的なあいさつや感謝を表すときに行います。',612,'04 · おじぎ','Dari gambar, mana yang merupakan 「敬礼」?','敬礼 sekitar 30 derajat, dipakai untuk sapaan umum atau menyampaikan terima kasih.','[{"k": "敬礼", "b": "けいれい", "a": "bungkuk 30°"}, {"k": "一般的", "b": "いっぱんてき", "a": "umum"}, {"k": "表す", "b": "あらわす", "a": "menyatakan"}]'::jsonb,'["aset/img/ojigi/sudut-15.png", "aset/img/ojigi/sudut-45.png", "aset/img/ojigi/sudut-30.png", "aset/img/ojigi/sudut-90.png"]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata,pilihan_gambar) values ('宿泊分野','写真の中で、正しいおじぎの姿勢はどれですか？','[]'::jsonb,2,'背筋を伸ばし腰から上体を曲げます。頭だけ下げる・ひざを曲げる・ポケットに手を入れるのは失礼です。',613,'04 · おじぎ','Dari gambar, mana postur membungkuk yang benar?','Punggung lurus dan badan dibungkukkan dari pinggang. Menundukkan kepala saja, menekuk lutut, atau tangan di kantong itu tidak sopan.','[{"k": "姿勢", "b": "しせい", "a": "postur"}, {"k": "背筋", "b": "せすじ", "a": "punggung"}, {"k": "曲げる", "b": "まげる", "a": "membungkukkan"}]'::jsonb,'["aset/img/ojigi/salah-kepala-saja.png", "aset/img/ojigi/salah-lutut.png", "aset/img/ojigi/sudut-30.png", "aset/img/ojigi/tangan-kantong.png"]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata,pilihan_gambar) values ('宿泊分野','女性がおじぎをするとき、手はどこに置きますか？','[]'::jsonb,0,'女性は両手を前で重ねるのが基本です。',614,'04 · おじぎ','Saat membungkuk, di mana posisi tangan wanita?','Wanita menumpuk kedua tangan di depan tubuh.','[{"k": "両手", "b": "りょうて", "a": "kedua tangan"}, {"k": "重ねる", "b": "かさねる", "a": "menumpuk"}, {"k": "基本", "b": "きほん", "a": "dasar"}]'::jsonb,'["aset/img/ojigi/tangan-depan.png", "aset/img/ojigi/tangan-samping.png", "aset/img/ojigi/tangan-kantong.png", "aset/img/ojigi/tangan-belakang.png"]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata,pilihan_gambar) values ('宿泊分野','男性がおじぎをするとき、手はどこに置きますか？','[]'::jsonb,0,'男性は腕を体の横に伸ばします。',615,'04 · おじぎ','Saat membungkuk, di mana posisi tangan pria?','Pria meluruskan lengan di samping badan.','[{"k": "腕", "b": "うで", "a": "lengan"}, {"k": "体の横", "b": "からだのよこ", "a": "samping badan"}, {"k": "伸ばす", "b": "のばす", "a": "meluruskan"}]'::jsonb,'["aset/img/ojigi/tangan-samping.png", "aset/img/ojigi/tangan-depan.png", "aset/img/ojigi/tangan-kantong.png", "aset/img/ojigi/tangan-belakang.png"]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','お客様を車から降りる際にドアを開け、最敬礼をする場面はいつですか？','["チェックインの受付時", "お見送り・お出迎えのとき", "館内清掃のとき", "電話応対のとき"]'::jsonb,1,'車のドアを開けて最敬礼するのは、お出迎え・お見送りの丁寧な場面です。',616,'04 · おじぎ','Kapan membukakan pintu mobil tamu lalu memberi 最敬礼?','Membukakan pintu mobil dengan 最敬礼 adalah momen sopan saat menyambut atau mengantar tamu pulang.','[{"k": "お見送り", "b": "おみおくり", "a": "mengantar pulang"}, {"k": "お出迎え", "b": "おでむかえ", "a": "menyambut"}, {"k": "丁寧", "b": "ていねい", "a": "sopan"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','お客様が帽子を被っているとき、おじぎはどうしますか？','["帽子のままおじぎする", "帽子を取り、お客様が離れるまで待つ", "帽子をかぶったまま頭だけ下げる", "帽子を取らずに会釈もしない"]'::jsonb,1,'お客様とあいさつするときは帽子を取るのがマナーです。',617,'04 · おじぎ','Kalau tamu memakai topi, bagaimana sikap kita saat menyapa?','Etikanya melepas topi saat menyapa tamu.','[{"k": "帽子", "b": "ぼうし", "a": "topi"}, {"k": "取る", "b": "とる", "a": "melepas"}, {"k": "マナー", "b": "まなー", "a": "etika"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','おじぎとあいさつの言葉のタイミングとして正しいのはどれですか？','["先に深くおじぎしてから話す", "言葉と同時におじぎする", "話し終わってからおじぎする", "おじぎはせずに言葉だけ"]'::jsonb,1,'「いらっしゃいませ」などは言葉とおじぎを同時に行うと自然です。',618,'04 · おじぎ','Kapan waktu yang benar antara ucapan dan bungkuk?','Ucapan seperti 「いらっしゃいませ」 sebaiknya bersamaan dengan bungkuk agar terasa wajar.','[{"k": "同時", "b": "どうじ", "a": "bersamaan"}, {"k": "自然", "b": "しぜん", "a": "wajar"}, {"k": "言葉", "b": "ことば", "a": "ucapan"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','お客様がエレベーターを降りるとき、従業員はどうしますか？','["先に降りて待つ", "お客様を先に降ろし、おじぎをする", "中で待ち続ける", "話しかけて止める"]'::jsonb,1,'お客様を優先し、降りたあとに丁寧におじぎをします。',619,'04 · おじぎ','Saat tamu keluar dari lift, apa yang dilakukan staf?','Utamakan tamu, lalu beri bungkuk sopan setelah tamu keluar.','[{"k": "降りる", "b": "おりる", "a": "turun/keluar"}, {"k": "優先", "b": "ゆうせん", "a": "memprioritaskan"}, {"k": "従業員", "b": "じゅうぎょういん", "a": "karyawan"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','お客様と並んで歩くときの位置として正しいのはどれですか？','["お客様の前に出て先導する", "お客様の後ろからついていく", "お客様の右後ろを少し下がって歩く", "並んで肩を組む"]'::jsonb,2,'お客様の右後ろを少し下がって歩くのが基本です。',620,'04 · おじぎ','Posisi yang benar saat berjalan bersama tamu?','Dasar: berjalan sedikit di belakang kanan tamu.','[{"k": "並ぶ", "b": "ならぶ", "a": "berdampingan"}, {"k": "後ろ", "b": "うしろ", "a": "belakang"}, {"k": "先導", "b": "せんどう", "a": "memimpin jalan"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','カウンター越しのおじぎで気をつけることはどれですか？','["カウンターに寄りかかっておじぎする", "一歩下がってからおじぎをする", "カウンターの上に手をつく", "顔だけ下げる"]'::jsonb,1,'カウンターに近すぎる場合は一歩下がり、頭が当たらないようおじぎをします。',621,'04 · おじぎ','Apa yang diperhatikan saat membungkuk di balik meja resepsionis?','Kalau terlalu dekat meja, mundur satu langkah lalu membungkuk agar kepala tidak terbentur.','[{"k": "カウンター", "b": "かうんたー", "a": "meja resepsionis"}, {"k": "下がる", "b": "さがる", "a": "mundur"}, {"k": "近い", "b": "ちかい", "a": "dekat"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','電話を切ったあと、するべきことはどれですか？','["すぐに次の作業に戻る", "受話器を置いてから軽く会釈する", "大きな声でお礼を言う", "電話を切らずに待つ"]'::jsonb,1,'電話でも相手を敬う気持ちを表すため、切ったあとに会釈をすることがあります。',622,'04 · おじぎ','Setelah menutup telepon, apa yang sebaiknya dilakukan?','Sebagai bentuk penghormatan, setelah menutup telepon kadang dilakukan 会釈 ringan.','[{"k": "受話器", "b": "じゅわき", "a": "gagang telepon"}, {"k": "敬う", "b": "うやまう", "a": "menghormati"}, {"k": "気持ち", "b": "きもち", "a": "perasaan"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','お客様を叱られた・お詫びするときのおじぎで正しいのはどれですか？','["会釈で軽く謝る", "最敬礼で丁寧に謝る", "頭を下げずに説明する", "笑顔でごまかす"]'::jsonb,1,'お詫びは最敬礼（約45度）で、言葉でも丁寧に謝罪します。',623,'04 · おじぎ','Mana bungkuk yang benar saat meminta maaf ke tamu?','Permintaan maaf memakai 最敬礼 (sekitar 45°) disertai ucapan maaf yang sopan.','[{"k": "謝る", "b": "あやまる", "a": "meminta maaf"}, {"k": "最敬礼", "b": "さいけいれい", "a": "bungkuk 45°"}, {"k": "説明", "b": "せつめい", "a": "penjelasan"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','おじぎをしている間に相手と目を合わせるのは正しいですか？','["正しい。ずっと見つめる", "正しくない。頭を下げたら目線も下げる", "正しい。顔だけ上げて見る", "どちらでもよい"]'::jsonb,1,'頭を下げたときは目線も自然に下げます。下げたまま相手を見るのは失礼です。',624,'04 · おじぎ','Bolehkah menatap lawan bicara saat sedang membungkuk?','Saat menunduk, pandangan ikut turun secara wajar. Menatap sambil menunduk itu tidak sopan.','[{"k": "目を合わせる", "b": "めをあわせる", "a": "menatap mata"}, {"k": "目線", "b": "めせん", "a": "arah pandang"}, {"k": "自然", "b": "しぜん", "a": "wajar"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','新人がおじぎを練習するときに最初に身につけるべきことはどれですか？','["早く深く下げること", "正しい姿勢と角度・タイミング", "大きな声を出すこと", "笑顔を保つことだけ"]'::jsonb,1,'まず姿勢・角度・タイミングという基本を正確に身につけます。',625,'04 · おじぎ','Apa yang pertama dikuasai pemula saat berlatih ojigi?','Pertama kuasai dasar secara tepat: postur, sudut, dan waktunya.','[{"k": "身につける", "b": "みにつける", "a": "menguasai"}, {"k": "角度", "b": "かくど", "a": "sudut"}, {"k": "新人", "b": "しんじん", "a": "karyawan baru"}]'::jsonb);
